#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

#define MAX_TERMS 200
#define MAX_ABS_NUM 100000

int main(int argc, char *argv[])
{
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }

    char *endptr;
    errno = 0;
    long num = strtol(argv[1], &endptr, 10);
    if (errno != 0 || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    errno = 0;
    long den = strtol(argv[2], &endptr, 10);
    if (errno != 0 || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    if (den == 0) {
        puts("BAD_INPUT");
        return 0;
    }
    if (num == 0) {
        puts("BAD_INPUT");
        return 0;
    }
    if (num > MAX_ABS_NUM || num < -MAX_ABS_NUM) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    long quotients[MAX_TERMS];
    int qcnt = 0;
    long a = num, b = den;
    while (b != 0) {
        if (qcnt >= MAX_TERMS) {
            puts("OUT_OF_RANGE");
            return 0;
        }
        long q = a / b;
        long r = a % b;
        quotients[qcnt++] = q;
        a = b;
        b = r;
    }

    putchar('[');
    if (qcnt > 0) {
        printf("%ld", quotients[0]);
        if (qcnt > 1) {
            printf("; %ld", quotients[1]);
            for (int i = 2; i < qcnt; ++i) {
                printf(", %ld", quotients[i]);
            }
        }
    }
    puts("]");
    return 0;
}
